import * as T from 'three';
import {NPCS,collectLoot} from './campaign.js';
import {distance,clamp,pointBlocked,hasLineOfSight} from './combat.js';
const rarityColor={common:0xc8c3a6,uncommon:0x9dc59c,rare:0x8cbed2,legendary:0xe5b66b};
export class VillageLife{
 constructor({scene,camera,player,state,cloneModel,obstacles,onTalk,onCollect,onApproach}){Object.assign(this,{scene,camera,player,state,obstacles,onTalk,onCollect,onApproach});this.npcs=[];this.drops=[];this.pending=null;this.layer=document.getElementById('world-labels');for(const data of NPCS){const model=cloneModel(data.model);model.position.set(data.x,0,data.z);model.rotation.y=.6;scene.add(model);const label=document.createElement('button');label.className='world-label npc-label';label.innerHTML=`<span class="npc-mark">${data.id==='rowan'?'◇':'◆'}</span>${data.name}<small>${data.role}</small>`;label.onclick=()=>this.interact(data.id);this.layer.append(label);const ring=new T.Mesh(new T.RingGeometry(.42,.47,32),new T.MeshBasicMaterial({color:data.color,transparent:true,opacity:.35,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.set(data.x,.11,data.z);scene.add(ring);this.npcs.push({...data,model,label,ring});}}
 find(id){return this.npcs.find(n=>n.id===id)||this.drops.find(d=>d.id===id&&!d.claimed);}
 interact(id){const target=id?this.find(id):this.nearest();if(!target)return{ok:false,reason:'Move closer to a villager or a loot drop.'};if(distance(this.player.position,target.model.position)>2.8||!hasLineOfSight(this.player.position,target.model.position,this.obstacles)){const p=target.model.position;if(this.onApproach({x:p.x,z:p.z})){this.pending=target.id;return{ok:true,approaching:target.name};}return{ok:false,reason:'That path is blocked.'};}this.pending=null;if(target.kind)return this.pickup(target);this.onTalk(target.id);return{ok:true,npc:target.id};}
 nearest(){const nearby=this.drops.filter(d=>!d.claimed&&distance(d.model.position,this.player.position)<2.8&&(d.kind!=='potion'||this.state.potions<5)&&hasLineOfSight(d.model.position,this.player.position,this.obstacles)).sort((a,b)=>(b.rarity==='legendary')-(a.rarity==='legendary')||distance(a.model.position,this.player.position)-distance(b.model.position,this.player.position));if(nearby.length)return nearby[0];return this.npcs.filter(n=>distance(n.model.position,this.player.position)<3.3&&hasLineOfSight(n.model.position,this.player.position,this.obstacles)).sort((a,b)=>distance(a.model.position,this.player.position)-distance(b.model.position,this.player.position))[0]||null;}
 pickup(drop){if(distance(this.player.position,drop.model.position)>2.8||!hasLineOfSight(this.player.position,drop.model.position,this.obstacles))return{ok:false,reason:'Move closer to collect this.'};const result=collectLoot(this.state,drop);if(!result.collected)return{ok:false,reason:result.reason};drop.label.remove();this.scene.remove(drop.model);drop.model.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});this.onCollect(drop,result);return{ok:true,...result};}
 addLoot(records,position){records.forEach((record,i)=>{const a=i/records.length*Math.PI*2;let x=position.x+Math.cos(a)*.65,z=position.z+Math.sin(a)*.65;const blocked=(x,z)=>pointBlocked({x,z},this.obstacles,.3);if(blocked(x,z)){x=position.x;z=position.z;}const model=new T.Group();model.position.set(x,0,z);const color=rarityColor[record.rarity];const geometry=record.kind==='item'?new T.OctahedronGeometry(.18):record.kind==='potion'?new T.CylinderGeometry(.11,.16,.32,8):new T.IcosahedronGeometry(.19);const mesh=new T.Mesh(geometry,new T.MeshStandardMaterial({color:record.kind==='potion'?0xb54c49:color,metalness:.5,roughness:.35,emissive:color,emissiveIntensity:.3}));mesh.position.y=.28;model.add(mesh);if(record.kind==='item'){const beam=new T.Mesh(new T.CylinderGeometry(.025,.12,record.rarity==='legendary'?4:2.2,12,1,true),new T.MeshBasicMaterial({color,transparent:true,opacity:.2,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending}));beam.position.y=record.rarity==='legendary'?2:1.1;model.add(beam);const ring=new T.Mesh(new T.RingGeometry(.22,.29,32),new T.MeshBasicMaterial({color,transparent:true,opacity:.8,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.y=.12;model.add(ring);}this.scene.add(model);const label=document.createElement('button');label.className=`world-label loot-label ${record.rarity}`;label.textContent=(record.kind==='gold'?`${record.amount} `:'')+record.name;label.onclick=()=>this.interact(record.id);this.layer.append(label);this.drops.push({...record,model,mesh,label,phase:i});});}
 update(t){for(const npc of this.npcs){const body=npc.model.getObjectByName('body');if(body)body.rotation.z=Math.sin(t*1.6+npc.x)*.015;if(distance(npc.model.position,this.player.position)<5)npc.model.rotation.y=Math.atan2(this.player.position.x-npc.x,this.player.position.z-npc.z);npc.ring.material.opacity=.26+Math.sin(t*2+npc.x)*.06;}for(const d of this.drops){if(d.claimed)continue;d.mesh.position.y=.28+Math.sin(t*2+d.phase)*.045;d.mesh.rotation.y=t*.4;if(d.kind==='gold'&&distance(d.model.position,this.player.position)<1.25)this.pickup(d);}if(this.pending){const target=this.find(this.pending);if(!target)this.pending=null;else if(distance(target.model.position,this.player.position)<2.7&&hasLineOfSight(target.model.position,this.player.position,this.obstacles))this.interact(target.id);}}
 renderLabels(inCombat=false,showAll=false){const occupied=[];const project=item=>item.model.position.clone().add(new T.Vector3(0,item.kind?.65:2.4,0)).project(this.camera);const hero=this.player.position.clone().add(new T.Vector3(0,1.1,0)).project(this.camera);occupied.push({x:(hero.x*.5+.5)*innerWidth-30,y:(-hero.y*.5+.5)*innerHeight-42,w:60,h:78});const sorted=[...this.npcs,...this.drops.filter(d=>!d.claimed).sort((a,b)=>(b.rarity==='legendary')-(a.rarity==='legendary')||a.id.localeCompare(b.id))];for(const item of sorted){const dist=distance(item.model.position,this.player.position),p=project(item);let visible=dist<(item.kind?showAll?17:10:17)&&Math.abs(p.x)<.96&&Math.abs(p.y)<.88&&p.z<1;if(item.kind&&!showAll&&(inCombat||item.kind==='gold'&&dist>4.5))visible=false;if((p.x*.5+.5)*innerWidth<310&&(-p.y*.5+.5)*innerHeight<370)visible=false;item.label.hidden=!visible;if(!visible)continue;let x=(p.x*.5+.5)*innerWidth,y=(-p.y*.5+.5)*innerHeight;const w=item.kind?Math.min(240,item.label.textContent.length*6.1+20):150,h=item.kind?23:59;if(item.kind){x=clamp(x,w/2+12,innerWidth-w/2-12);let chosen=null;for(const offset of [0,25,50,75,-25,-50,100,-75,125]){const candidate={x:x-w/2,y:y+offset-h,w,h};if(candidate.y<95||candidate.y+h>innerHeight-170)continue;if(!occupied.some(r=>candidate.x<r.x+r.w+4&&candidate.x+candidate.w>r.x-4&&candidate.y<r.y+r.h+3&&candidate.y+candidate.h>r.y-3)){chosen=candidate;break;}}if(!chosen){item.label.hidden=true;continue;}y=chosen.y+h;occupied.push(chosen);}else occupied.push({x:x-w/2,y:y-h,w,h});item.label.style.left=`${x}px`;item.label.style.top=`${y}px`;item.label.classList.toggle('in-reach',dist<2.8);}}
 getState(){return{npcs:this.npcs.map(n=>({id:n.id,name:n.name,role:n.role,x:n.x,z:n.z,inReach:distance(n.model.position,this.player.position)<2.8})),loot:this.drops.filter(d=>!d.claimed).map(d=>({id:d.id,name:d.name,kind:d.kind,rarity:d.rarity,amount:d.amount,template:d.template,x:d.model.position.x,z:d.model.position.z,inReach:distance(d.model.position,this.player.position)<2.8}))};}
}
